package org.alexmond.maven.claude.context;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Renders {@link ModuleFacts} as the markdown file Claude Code reads through a
 * {@code @.claude/maven-context.md} import in CLAUDE.md.
 */
public final class ContextRenderer {

	/**
	 * Marker on the first line; lets init tell a generated file from a hand-written one.
	 */
	public static final String MARKER = "<!-- Generated by claude-maven-plugin";

	private ContextRenderer() {
	}

	/**
	 * Renders the context.
	 * @param modules reactor modules, root first
	 * @param mvn the Maven command to show ({@code ./mvnw} or {@code mvn})
	 * @return markdown text
	 */
	public static String render(List<ModuleFacts> modules, String mvn) {
		ModuleFacts root = modules.get(0);
		boolean multi = modules.size() > 1;
		StringBuilder md = new StringBuilder();
		md.append(MARKER).append(" (claude:context). Regenerate: ").append(mvn).append(" -q claude:context -->\n");
		md.append("# Maven project: ").append(title(root)).append("\n\n");

		List<String> facts = new ArrayList<>();
		facts.add("Build with `" + mvn + "`" + ("./mvnw".equals(mvn) ? " (Maven wrapper)" : ""));
		String java = firstNonNull(modules.stream().map(ModuleFacts::javaRelease).toList());
		if (java != null) {
			facts.add("Java " + java);
		}
		facts.add(multi ? modules.size() + " modules" : "packaging `" + root.packaging() + "`");
		Set<String> tests = union(modules, ModuleFacts::testStack);
		if (!tests.isEmpty()) {
			facts.add("tests: " + String.join(", ", tests));
		}
		if (modules.stream().anyMatch(ModuleFacts::integrationTests)) {
			facts.add("integration tests via failsafe (`*IT`, run by `verify`)");
		}
		if (modules.stream().anyMatch(ModuleFacts::springBoot)) {
			facts.add("Spring Boot");
		}
		md.append("- ").append(String.join(" · ", facts)).append("\n\n");

		if (multi) {
			md.append("## Modules\n\n");
			md.append("| Module | Path | Packaging | Depends on (in this build) |\n");
			md.append("|---|---|---|---|\n");
			for (ModuleFacts module : modules) {
				md.append("| ")
					.append(module.artifactId())
					.append(" | `")
					.append(module.path())
					.append("` | ")
					.append(module.packaging())
					.append(" | ")
					.append(module.reactorDependencies().isEmpty() ? "—"
							: String.join(", ", module.reactorDependencies()))
					.append(" |\n");
			}
			md.append('\n');
		}

		appendCommands(md, modules, mvn, multi);

		Set<String> checks = union(modules, ModuleFacts::checks);
		if (!checks.isEmpty()) {
			md.append("## Checks that fail the build\n\n");
			md.append(String.join(", ", checks))
				.append(". They run as part of the normal lifecycle, so `")
				.append(mvn)
				.append(" -q verify` is the check to pass before calling work done.\n\n");
		}

		List<String> profileRows = new ArrayList<>();
		for (ModuleFacts module : modules) {
			for (ModuleFacts.Profile profile : module.profiles()) {
				profileRows
					.add("| " + profile.id() + " | " + module.artifactId() + " | " + profile.activation() + " |");
			}
		}
		if (!profileRows.isEmpty()) {
			md.append("## Profiles\n\n| Profile | Declared in | Activation |\n|---|---|---|\n");
			profileRows.forEach((row) -> md.append(row).append('\n'));
			md.append('\n');
		}

		md.append("## Build output\n\n");
		md.append("With the claude-maven-plugin extension in `.mvn/extensions.xml`, builds run from Claude Code print ")
			.append("only a summary: compile errors and failing tests with `file:line`, trimmed to project frames. ")
			.append("The full log is in `target/claude/build.log`, structured results in ")
			.append("`target/claude/build-report.json`. Add `-Dclaude.output=off` to see normal Maven output.\n");
		return md.toString();
	}

	private static void appendCommands(StringBuilder md, List<ModuleFacts> modules, String mvn, boolean multi) {
		String example = multi ? modules.get(modules.size() - 1).path() : null;
		md.append("## Commands\n\n| Task | Command |\n|---|---|\n");
		row(md, "Build and run all checks", mvn + " -q verify");
		if (multi) {
			row(md, "One module (and what it needs)", mvn + " -q -pl " + example + " -am verify");
			row(md, "One test class / method", mvn + " -q -pl " + example
					+ " -am test -Dtest='FooTest#bar' -Dsurefire.failIfNoSpecifiedTests=false");
		}
		else {
			row(md, "One test class / method", mvn + " -q test -Dtest='FooTest#bar'");
		}
		if (modules.stream().anyMatch(ModuleFacts::integrationTests)) {
			row(md, "One integration test",
					mvn + " -q verify -Dit.test=FooIT -Dtest=none -Dsurefire.failIfNoSpecifiedTests=false");
		}
		row(md, "Package without tests", mvn + " -q package -DskipTests");
		for (String fix : union(modules, ModuleFacts::formatCommands)) {
			row(md, "Fix formatting", mvn + " " + fix);
		}
		if (modules.stream().anyMatch(ModuleFacts::springBoot)) {
			String app = modules.stream()
				.filter(ModuleFacts::springBoot)
				.map(ModuleFacts::path)
				.findFirst()
				.orElse(".");
			row(md, "Run the app", mvn + (".".equals(app) ? "" : " -pl " + app) + " spring-boot:run");
		}
		row(md, "Read a dependency's source", mvn + " -q claude:source -Dclass=com.example.SomeClass");
		row(md, "Dependency tree", mvn + " -q dependency:tree" + (multi ? " -pl " + example : ""));
		md.append('\n');
	}

	private static void row(StringBuilder md, String task, String command) {
		md.append("| ").append(task).append(" | `").append(command).append("` |\n");
	}

	private static String title(ModuleFacts root) {
		String name = (root.name() != null && !root.name().isBlank()) ? root.name() : root.artifactId();
		return name + " (`" + root.coordinates() + "`)";
	}

	private static Set<String> union(List<ModuleFacts> modules,
			java.util.function.Function<ModuleFacts, List<String>> values) {
		Set<String> result = new LinkedHashSet<>();
		modules.forEach((module) -> result.addAll(values.apply(module)));
		return result;
	}

	private static String firstNonNull(List<String> values) {
		for (String value : values) {
			if (value != null) {
				return value;
			}
		}
		return null;
	}

}
